<?= $this->extend('layout') ?>
<?= $this->section('content') ?>
<div class="page-heading"><div><p class="eyebrow"><?= esc($ticket['ticket_no']) ?></p><h1><?= esc($ticket['title']) ?></h1><p class="text-secondary">Diajukan <?= esc($ticket['requester_name']) ?> · <?= esc(local_time($ticket['created_at'])) ?></p></div><a href="<?= site_url('tickets') ?>" class="btn btn-outline-secondary">Kembali</a></div>
<div class="row g-3"><div class="col-lg-8"><div class="panel mb-3"><div class="d-flex flex-wrap gap-2 mb-3"><span class="badge text-bg-primary"><?= esc($ticket['status']) ?></span><span class="badge text-bg-secondary"><?= esc($ticket['priority']) ?></span><span class="badge text-bg-light text-dark"><?= esc($ticket['category_name']) ?></span><?php if ($overdue): ?><span class="badge text-bg-danger">Lewat SLA</span><?php endif ?></div><p style="white-space:pre-wrap"><?= esc($ticket['description']) ?></p><hr><small class="text-secondary">Tenggat SLA: <?= esc(local_time($ticket['sla_due_at'])) ?></small></div>
<?php if (\App\Services\TicketService::canParticipate($ticket, (int) session('user_id'), (string) session('role'))): ?>
<div class="panel mb-3"><h2>Komentar</h2><?php foreach ($comments as $c): ?><div class="border-bottom py-3"><strong><?= esc($c['name']) ?></strong><small class="text-secondary ms-2"><?= esc(local_time($c['created_at'])) ?></small><p class="mb-0 mt-1" style="white-space:pre-wrap"><?= esc($c['body']) ?></p></div><?php endforeach ?>
<form method="post" action="<?= site_url('tickets/' . $ticket['id'] . '/comments') ?>" class="mt-3"><?= csrf_field() ?><label class="form-label">Tulis komentar</label><textarea name="body" class="form-control mb-2" rows="3" required></textarea><button class="btn btn-primary">Kirim komentar</button></form></div>
<div class="panel"><h2>Lampiran</h2><ul><?php foreach ($attachments as $a): ?><li><a href="<?= site_url('attachments/' . $a['id']) ?>"><?= esc($a['original_name']) ?></a> (<?= round($a['size']/1024) ?> KB)</li><?php endforeach ?></ul><?php if (count($attachments) < 3): ?><form method="post" enctype="multipart/form-data" action="<?= site_url('tickets/' . $ticket['id'] . '/attachments') ?>"><?= csrf_field() ?><input type="file" class="form-control mb-2" name="attachment" accept=".jpg,.jpeg,.png,.pdf" required><small class="text-secondary d-block mb-2">JPG, PNG, PDF · maksimal 2 MB · maksimal 3 berkas/tiket</small><button class="btn btn-outline-primary">Unggah lampiran</button></form><?php endif ?></div>
<?php endif ?></div>
<div class="col-lg-4"><div class="panel mb-3"><h2>Tindakan</h2>
<?php if ($ticket['deleted_at']): ?><div class="alert alert-warning">Tiket telah dihapus.</div><?php endif ?>
<?php if (! $ticket['deleted_at'] && (session('role') === 'admin' || (session('role') === 'pemohon' && $ticket['status'] === 'Baru' && (int) $ticket['user_id'] === (int) session('user_id')))): ?><a href="<?= site_url('tickets/' . $ticket['id'] . '/edit') ?>" class="btn btn-outline-primary mb-3">Ubah isi tiket</a><?php endif ?>
<?php if ($ticket['status'] === 'Baru' && ! $ticket['assigned_to'] && in_array(session('role'), ['petugas','admin'], true)): ?><form method="post" action="<?= site_url('tickets/' . $ticket['id'] . '/take') ?>" class="mb-3"><?= csrf_field() ?><button class="btn btn-primary">Ambil tiket</button></form><?php endif ?>
<?php $canStatus = (session('role') === 'admin' && $ticket['status'] !== 'Ditutup') || (session('role') === 'petugas' && (int) $ticket['assigned_to'] === (int) session('user_id') && $ticket['status'] === 'Diproses') || (session('role') === 'pemohon' && (int) $ticket['user_id'] === (int) session('user_id') && $ticket['status'] === 'Selesai'); ?>
<?php if ($canStatus && ! $ticket['deleted_at']): ?><form method="post" action="<?= site_url('tickets/' . $ticket['id'] . '/status') ?>" class="mb-3"><?= csrf_field() ?><label class="form-label">Ubah status</label><select name="status" class="form-select mb-2"><?php if (session('role') === 'admin'): ?><?php foreach (['Baru','Diproses','Selesai','Ditutup'] as $s): ?><option value="<?= $s ?>"><?= $s ?></option><?php endforeach ?><?php elseif ($ticket['status'] === 'Diproses'): ?><option value="Selesai">Selesai</option><?php else: ?><option value="Diproses">Buka ulang</option><option value="Ditutup">Tutup</option><?php endif ?></select><textarea class="form-control mb-2" name="note" placeholder="Catatan / alasan wajib" required></textarea><button class="btn btn-primary">Simpan status</button></form><?php endif ?>
<?php if (session('role') === 'admin' && ! $ticket['deleted_at']): ?><form method="post" action="<?= site_url('tickets/' . $ticket['id'] . '/priority') ?>" class="mb-3"><?= csrf_field() ?><label class="form-label">Prioritas</label><select class="form-select mb-2" name="priority"><?php foreach (['Rendah','Sedang','Tinggi','Kritis'] as $p): ?><option value="<?= $p ?>" <?= $ticket['priority'] === $p ? 'selected' : '' ?>><?= $p ?></option><?php endforeach ?></select><input class="form-control mb-2" name="reason" placeholder="Alasan perubahan" required><button class="btn btn-outline-primary">Ubah prioritas</button></form><?php if ($ticket['status'] !== 'Ditutup'): ?><form method="post" action="<?= site_url('tickets/' . $ticket['id'] . '/assign') ?>" class="mb-3"><?= csrf_field() ?><label class="form-label">Tugaskan / pindahkan petugas</label><select class="form-select mb-2" name="officer_id"><?php foreach ($officers as $o): ?><option value="<?= (int) $o['id'] ?>" <?= (int) $ticket['assigned_to'] === (int) $o['id'] ? 'selected' : '' ?>><?= esc($o['name']) ?></option><?php endforeach ?></select><input class="form-control mb-2" name="reason" placeholder="Alasan penugasan" required><button class="btn btn-outline-primary">Simpan penugasan</button></form><?php endif ?><form method="post" action="<?= site_url('tickets/' . $ticket['id'] . '/delete') ?>" onsubmit="return confirm('Hapus tiket ini?')"><?= csrf_field() ?><button class="btn btn-outline-danger">Hapus tiket</button></form><?php endif ?></div>
<div class="panel"><h2>Riwayat status</h2><?php foreach ($logs as $log): ?><div class="border-start border-3 border-primary ps-3 mb-3"><strong><?= esc($log['old_status']) ?> → <?= esc($log['new_status']) ?></strong><small class="d-block text-secondary"><?= esc(local_time($log['changed_at'])) ?></small></div><?php endforeach ?><?php if (! $logs): ?><p class="text-secondary">Belum ada perubahan status.</p><?php endif ?></div></div></div>
<?= $this->endSection() ?>
